TEST(ParserTest, ReadsPort) {
  auto config = parse_config("port = 8080\n");
  ASSERT_NE(config, nullptr);
  EXPECT_EQ(config->port, 8080);
}

TEST(ParserTest, ReadsHosts) {
  auto config = parse_config("hosts = a, b\n");
  ASSERT_NE(config, nullptr);
  ASSERT_EQ(config->hosts.size(), 2u);
  EXPECT_EQ(config->hosts[0], "a");
}

void ParseOrFail(const std::string& text, std::unique_ptr<Config>* out) {
  *out = parse_config(text);
  ASSERT_NE(*out, nullptr) << "input: " << text;
}

TEST(ParserTest, ReadsHosts) {
  std::unique_ptr<Config> config;
  ASSERT_NO_FATAL_FAILURE(ParseOrFail("hosts = a, b\n", &config));
  ASSERT_EQ(config->hosts.size(), 2u);
  EXPECT_EQ(config->hosts[0], "a");
}
